"""Generate compatible TypeScript and Dart registries from the bounded wire contract."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CONTRACT = ROOT / "backend/src/recallstack/modules/telemetry/registry.json"


def generate() -> None:
    events = json.loads(CONTRACT.read_text())["events"]
    types = {"count": "number", "duration": "number", "active": "number", "bool": "boolean"}
    lines = [
        "// Generated by backend/scripts/generate_telemetry.py. Do not edit.",
        "export interface EventProperties {",
    ]
    for name, spec in events.items():
        fields = []
        for key, kind in spec["properties"].items():
            value = (
                " | ".join(json.dumps(v) for v in kind)
                if isinstance(kind, list)
                else types.get(kind, "string")
            )
            fields.append(f"{key}?: {value}")
        property_type = "{ " + "; ".join(fields) + " }" if fields else "Record<string, never>"
        lines.append(f'  "{name}": {property_type};')
    lines += [
        "}",
        "export type EventName = keyof EventProperties;",
        "export const registry = " + json.dumps(events, indent=2) + " as const;\n",
    ]
    (ROOT / "web/src/lib/telemetry").mkdir(exist_ok=True)
    (ROOT / "web/src/lib/telemetry/registry.ts").write_text("\n".join(lines), encoding="utf-8")
    # Runtime validation in Dart uses the same property schemas, with an enum for event names.
    dart = [
        "// Generated by backend/scripts/generate_telemetry.py. Do not edit.",
        "import 'dart:convert';",
        "enum TelemetryEvent {",
    ]
    for name in events:
        feature_words = name.split(".")[0].split("_")
        feature_name = feature_words[0] + "".join(p.title() for p in feature_words[1:])
        dart_name = feature_name + "".join(p.title() for p in name.split(".")[1].split("_"))
        dart.append(f"  {dart_name}('{name}'),")
    dart += [
        "  ;",
        "  const TelemetryEvent(this.wire);",
        "  final String wire;",
        "}",
        "final telemetryRegistry = jsonDecode(r'''"
        + json.dumps(events)
        + "''') as Map<String, dynamic>;\n",
    ]
    (ROOT / "mobile/lib/core/telemetry/registry.dart").write_text("\n".join(dart), encoding="utf-8")


if __name__ == "__main__":
    generate()
